// === Tab: mySketch ===
let theShader;

function setup() {
	createCanvas(1000, 1000,WEBGL);
	noStroke()
	background(0);
}


function preload(){
	theShader = createShader(vert, frag)
}

function draw() {
	shader(theShader)
	theShader.setUniform('u_resolution',[width/1000,height/1000])
	theShader.setUniform('u_time',millis()/1000)
	theShader.setUniform('u_mouse',[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width,(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height])

	//translate(sin(frameCount/50)+random(width),sin(frameCount/80)+random(width))
	translate(0,0)
	push()
		rotate(frameCount/50)
		ellipse(noise(-50,50)*120, noise(-50,50)*120, 400, 600);
	pop()

}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

// === Tab: frag ===



const frag =`
	precision mediump float;

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform float u_time;

	varying vec2 var_vertTexCoord;
	void main() {
			vec2 st = var_vertTexCoord.xy/u_resolution;
			st.x *= u_resolution.x/u_resolution.y;


			vec3 color = vec3(0.);

			color = vec3(st.x,st.y,abs(sin(u_time)));
			gl_FragColor = vec4(color,1.0);
	}

`

// === Tab: vert ===
//ref 3d shader from https://www.openprocessing.org/sketch/881537

const vert = `
	precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;

